INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoarthritis','easy','flashcard','What is the primary structural protein of articular cartilage?','["Type II collagen"]','A','Articular cartilage extracellular matrix is predominantly type II collagen, distinguishing it from bone (type I collagen).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoarthritis','easy','flashcard','What is fibrillation in the context of osteoarthritis?','["Splitting and fraying of the articular cartilage surface creating a shaggy texture"]','A','Fibrillation is the earliest morphological change in OA cartilage representing superficial cracks along the articular surface due to loss of proteoglycan and collagen integrity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoarthritis','easy','flashcard','What is eburnation?','["Polished ivory-like appearance of subchondral bone exposed after complete cartilage loss in osteoarthritis"]','A','Eburnation occurs when cartilage is completely lost leaving sclerotic subchondral bone that becomes polished by friction against the opposing joint surface.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoarthritis','medium','flashcard','What are osteophytes and where do they form in osteoarthritis?','["Bony outgrowths (spurs) that develop at the margins of joints formed by endochondral ossification of periarticular fibrocartilage"]','A','Osteophytes are a radiological hallmark of OA and represent an attempted repair response. They can break off to form loose bodies (joint mice).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoarthritis','medium','flashcard','What are Heberden''s nodes and at which joints do they occur?','["Bony enlargements (osteophytes) at the DIP (distal interphalangeal) joints in osteoarthritis"]','A','Heberden''s nodes are characteristic of OA at DIP joints; contrast with Bouchard''s nodes at PIP joints. Both reflect osteophyte formation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoarthritis','medium','flashcard','What are Bouchard''s nodes in osteoarthritis?','["Bony enlargements (osteophytes) at the PIP (proximal interphalangeal) joints in osteoarthritis"]','A','Bouchard''s nodes at PIPs alongside Heberden''s nodes at DIPs are characteristic of primary OA of the hand; RA by contrast predominantly affects MCPs and PIPs with erosion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoarthritis','medium','flashcard','What are subchondral cysts in OA and how do they form?','["Fluid-filled cysts in subchondral bone formed when synovial fluid is forced into bone through cartilage defects under joint pressure"]','A','Subchondral cysts (geodes) are radiologically visible as lucent areas beneath the joint surface and result from synovial fluid intrusion through cartilage gaps.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoarthritis','medium','flashcard','Which cytokines drive cartilage destruction in osteoarthritis and what do they activate?','["IL-1 and TNF activate matrix metalloproteinases (MMPs) that degrade collagen and proteoglycans in articular cartilage"]','A','IL-1 and TNF are key mediators upregulating MMPs (collagenases gelatinases) and downregulating cartilage matrix synthesis by chondrocytes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoarthritis','hard','flashcard','What distinguishes primary from secondary osteoarthritis?','["Primary OA has no identifiable predisposing cause (idiopathic age-related); secondary OA results from a known condition such as prior joint injury obesity metabolic disease or congenital joint abnormality"]','A','Primary OA affects weight-bearing joints and hands in older individuals without a specific cause; secondary OA can affect any joint and occurs at a younger age due to an identifiable underlying condition.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoarthritis','hard','flashcard','What is the role of proteoglycans in articular cartilage and what happens to them in early OA?','["Proteoglycans (aggrecan) bind water and provide compressive resistance; in early OA they are degraded by MMPs and ADAMTS enzymes reducing water content and cartilage resilience"]','A','Loss of proteoglycan (primarily aggrecan) is an early OA event that reduces the cartilage''s ability to withstand compressive loads initiating the cycle of degradation.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Rheumatoid Arthritis','easy','flashcard','What is pannus in rheumatoid arthritis?','["Vascular granulation tissue that proliferates from the synovium and invades and destroys underlying cartilage and bone"]','A','Pannus is the hallmark destructive lesion of RA; it is driven by synovial fibroblast and macrophage activation and is responsible for the characteristic joint erosions seen on imaging.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Rheumatoid Arthritis','easy','flashcard','Which antibody is most specific for rheumatoid arthritis?','["Anti-CCP (anti-cyclic citrullinated peptide antibody) with approximately 95% specificity"]','A','Anti-CCP has ~95% specificity for RA (compared to ~85% for RF) and can be positive years before symptom onset. It is the most specific serological marker for RA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Rheumatoid Arthritis','easy','flashcard','What is rheumatoid factor (RF) and why is it not specific for RA?','["RF is IgM antibody directed against the Fc portion of IgG; it is found in RA but also in other conditions including SLE Sjogren''s syndrome infections and healthy elderly individuals"]','A','RF is present in ~80% of RA patients but lacks specificity; anti-CCP is more specific. RF positivity correlates with more severe disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Rheumatoid Arthritis','medium','flashcard','What is the HLA association of rheumatoid arthritis?','["HLA-DR4 (and HLA-DR1); the shared epitope on HLA-DRbeta1 presents citrullinated peptides to CD4+ T cells driving autoimmune synovitis"]','A','The shared epitope hypothesis explains HLA-DR4 association: a conserved amino acid sequence on HLA-DRbeta1 predisposes to RA by presenting citrullinated autoantigens to T helper cells.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Rheumatoid Arthritis','medium','flashcard','Which joints does RA preferentially involve and which joint does it classically spare?','["RA symmetrically involves PIP and MCP joints of the hands and MTP joints of the feet; it classically spares the DIP joints"]','A','Sparing of DIPs distinguishes RA from OA (which involves DIPs) and psoriatic arthritis (which preferentially involves DIPs).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Rheumatoid Arthritis','medium','flashcard','Describe swan-neck deformity in RA.','["PIP joint hyperextension combined with DIP joint flexion caused by imbalance of flexor and extensor tendons due to synovitis weakening the palmar plate"]','A','Swan-neck deformity results from synovitis weakening the palmar plate at the PIP joint allowing hyperextension. It is a late complication of untreated RA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Rheumatoid Arthritis','medium','flashcard','Describe boutonniere deformity in RA.','["PIP joint flexion combined with DIP joint extension caused by rupture of the central slip of the extensor tendon at the PIP joint"]','A','Boutonniere (buttonhole) deformity: the proximal phalanx head protrudes through the split extensor mechanism. It is the mirror image of swan-neck deformity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Rheumatoid Arthritis','medium','flashcard','What is the histological appearance of a rheumatoid nodule?','["Central zone of fibrinoid necrosis surrounded by palisading macrophages (histiocytes) with an outer layer of lymphocytes and plasma cells"]','A','Rheumatoid nodules occur in ~25% of RF-positive RA patients typically over pressure points. The fibrinoid necrosis with palisading histiocyte pattern is distinctive.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Rheumatoid Arthritis','hard','flashcard','What is Felty syndrome?','["The triad of rheumatoid arthritis plus splenomegaly plus neutropenia; associated with severe seropositive RA and increased risk of infections"]','A','Felty syndrome occurs in longstanding severe RA. Neutropenia results from splenic sequestration and bone marrow suppression. HLA-DR4 is strongly associated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Rheumatoid Arthritis','hard','flashcard','What extra-articular cardiac and pulmonary manifestations occur in RA?','["Pericarditis (most common cardiac), pleuritis with exudative effusion (very low glucose), pulmonary nodules and interstitial lung disease"]','A','Extra-articular RA reflects systemic immune complex deposition and granulomatous inflammation. Pleuritis in RA produces a characteristic very low glucose pleural fluid.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Gout & Pseudogout','easy','flashcard','What is the crystal shape in gout (monosodium urate)?','["Needle-shaped (acicular) crystals of monosodium urate often seen intracellularly within neutrophils in synovial fluid"]','A','MSU crystals are long thin and needle-shaped. They are found within neutrophils during acute attacks and in tophi in chronic disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Gout & Pseudogout','easy','flashcard','What is podagra?','["Acute gouty arthritis affecting the first metatarsophalangeal (MTP) joint; the classic initial presentation of gout"]','A','Podagra (first MTP joint) occurs in >50% of first gout attacks. The joint is red hot and exquisitely tender. The name derives from Greek meaning foot trap.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Gout & Pseudogout','easy','flashcard','What is the crystal shape in pseudogout (CPPD)?','["Rhomboid (rectangular/rhomboidal) shaped calcium pyrophosphate dihydrate (CPPD) crystals"]','A','The rhomboid shape of CPPD crystals distinguishes them from the needle-shaped MSU crystals of gout. CPPD often deposits in fibrocartilage such as menisci.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Gout & Pseudogout','medium','flashcard','What are the polarized light microscopy findings that distinguish urate from CPPD crystals?','["MSU (gout) crystals are negatively birefringent (yellow when parallel to the polarizer); CPPD (pseudogout) crystals are positively birefringent (blue when parallel to the polarizer)"]','A','Birefringence is the key microscopy distinction: n-Negative gout (needle-shaped negatively birefringent) versus p-Pseudogout (positively birefringent rhomboid).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Gout & Pseudogout','medium','flashcard','What are tophi and where do they classically deposit?','["Chalky white deposits of monosodium urate crystals surrounded by foreign body giant cell reaction; classically in the helix of the ear olecranon bursa Achilles tendon and periarticular tissue"]','A','Tophi are a feature of chronic tophaceous gout and represent persistent hyperuricemia with crystal deposition in avascular or poorly perfused tissues.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Gout & Pseudogout','medium','flashcard','What is the mechanism of the acute inflammatory response in gout?','["MSU crystals activate the NLRP3 inflammasome in macrophages and neutrophils leading to caspase-1 activation and cleavage of pro-IL-1beta to active IL-1beta triggering acute inflammation"]','A','The NLRP3 inflammasome-IL-1beta pathway is central to acute gout; this is why IL-1 inhibitors (anakinra canakinumab) are effective treatments for refractory gout.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Gout & Pseudogout','medium','flashcard','What is the mechanism of action of colchicine in gout?','["Colchicine inhibits microtubule polymerization by binding tubulin which impairs neutrophil migration phagocytosis and NLRP3 inflammasome activation reducing IL-1beta release"]','A','By disrupting microtubule assembly colchicine prevents neutrophil chemotaxis to the inflamed joint and inhibits NLRP3 inflammasome assembly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Gout & Pseudogout','medium','flashcard','What is the mechanism of allopurinol in treating gout?','["Allopurinol inhibits xanthine oxidase the enzyme that converts hypoxanthine to xanthine and xanthine to uric acid thereby reducing uric acid production"]','A','Allopurinol is a xanthine oxidase inhibitor for urate-lowering therapy in chronic gout. Febuxostat is a non-purine xanthine oxidase inhibitor alternative.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Gout & Pseudogout','hard','flashcard','What drugs and conditions trigger acute gout attacks?','["Thiazide and loop diuretics (reduce uric acid excretion) alcohol (increases urate production and reduces renal excretion) low-dose aspirin surgery/trauma dehydration and rapid urate level changes from starting urate-lowering therapy"]','A','Starting allopurinol or uricosuric agents can paradoxically trigger an acute attack due to crystal mobilization as urate levels change rapidly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Gout & Pseudogout','hard','flashcard','What is Lesch-Nyhan syndrome and how does it cause gout?','["X-linked recessive deficiency of HGPRT (hypoxanthine-guanine phosphoribosyltransferase) causing failure to salvage purines; purines are catabolized to uric acid causing severe hyperuricemia gout urate nephropathy neurological dysfunction and self-mutilation"]','A','HGPRT deficiency eliminates the purine salvage pathway; excess hypoxanthine and guanine are converted to uric acid via xanthine oxidase. Neurological features distinguish it from primary gout.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoporosis','easy','flashcard','How is osteoporosis defined at the tissue level?','["Decreased total bone mass (both cortical and trabecular) with normal bone mineralization (normal calcium:organic matrix ratio)"]','A','Osteoporosis is a quantitative defect in bone mass not a qualitative defect in mineralization (which would be osteomalacia). The bone present is normally mineralized but insufficient in amount.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoporosis','easy','flashcard','What are the DEXA T-score thresholds for osteoporosis and osteopenia?','["Osteoporosis: T-score less than or equal to -2.5; Osteopenia: T-score between -1.0 and -2.5; Normal: T-score greater than -1.0"]','A','T-score compares bone mineral density to a young healthy adult reference mean. Each SD below the mean roughly doubles fracture risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoporosis','easy','flashcard','What is the mechanism of action of bisphosphonates in osteoporosis?','["Bisphosphonates inhibit osteoclast-mediated bone resorption by being taken up by osteoclasts inhibiting farnesyl pyrophosphate synthase (mevalonate pathway) and inducing osteoclast apoptosis"]','A','Bisphosphonates are structurally similar to pyrophosphate bind hydroxyapatite at resorption sites and are internalized by osteoclasts where they disrupt the mevalonate pathway leading to osteoclast apoptosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoporosis','medium','flashcard','What is Type I (postmenopausal) osteoporosis and which bones does it preferentially affect?','["Type I occurs in postmenopausal women due to estrogen deficiency; preferentially affects trabecular (cancellous) bone causing vertebral compression fractures and Colles'' fractures of the distal radius"]','A','Estrogen normally suppresses RANKL expression and promotes OPG production inhibiting osteoclasts. Its loss causes rapid trabecular bone loss and fractures at trabecular-rich sites.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoporosis','medium','flashcard','What is Type II (senile) osteoporosis and what fracture is most feared?','["Type II affects both men and women over 70 years; involves both cortical and trabecular bone loss; femoral neck (NOF) fractures are most feared due to high mortality (~20-30% at 1 year)"]','A','Type II osteoporosis results from age-related decline in osteoblast activity and reduced calcium absorption. Femoral neck fractures are the most morbid fragility fractures.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoporosis','medium','flashcard','What is the RANKL/OPG pathway and how does estrogen interact with it?','["RANKL (on osteoblasts/stromal cells) binds RANK on osteoclast precursors promoting osteoclastogenesis; OPG is a decoy receptor blocking RANKL; estrogen upregulates OPG and downregulates RANKL thus inhibiting osteoclast activity"]','A','Denosumab is a monoclonal antibody against RANKL that mimics OPG action; it is used in osteoporosis when bisphosphonates are contraindicated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoporosis','medium','flashcard','What is the most common fracture site in osteoporosis overall?','["Vertebral compression fractures (thoracic and lumbar spine) are the most common osteoporotic fractures though many are clinically silent and discovered incidentally"]','A','Vertebral fractures may be asymptomatic or cause acute back pain height loss and kyphosis (dowager''s hump). They may be discovered incidentally on chest X-ray.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoporosis','medium','flashcard','What secondary causes of osteoporosis are most clinically important?','["Corticosteroid excess (inhibits osteoblasts and intestinal calcium absorption increases RANKL) hypogonadism hyperthyroidism multiple myeloma malabsorption hyperparathyroidism and immobilization"]','A','Secondary osteoporosis should always be excluded especially in younger patients or those with atypical fractures. Corticosteroids are the most common iatrogenic cause.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoporosis','hard','flashcard','At what age is peak bone mass typically achieved and why does this matter?','["Peak bone mass is achieved between ages 25-35 years; a higher peak bone mass provides a greater reserve before the osteoporotic threshold is reached later in life"]','A','Factors that optimize peak bone mass (adequate calcium vitamin D weight-bearing exercise avoidance of smoking/alcohol) during growth are the most effective long-term osteoporosis prevention strategy.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Osteoporosis','hard','flashcard','What is the difference between bisphosphonate mechanism and denosumab mechanism in osteoporosis?','["Bisphosphonates inhibit the osteoclast mevalonate pathway intracellularly causing apoptosis; denosumab is a monoclonal antibody against RANKL that prevents osteoclast differentiation and activation extracellularly — effects are rapidly reversible on stopping denosumab"]','A','On stopping denosumab bone density rapidly falls back to baseline or below (rebound effect); bisphosphonates persist in bone for years. This distinction has important clinical implications for treatment sequencing.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Systemic Lupus Erythematosus','easy','flashcard','Which antibody test is the best screening test for SLE and why?','["ANA (antinuclear antibody) is the best screening test — present in >95% of SLE patients giving high sensitivity; negative ANA virtually excludes SLE"]','A','A negative ANA has high negative predictive value making it ideal for screening. Low specificity (~65%) means positive ANA requires confirmatory specific antibody testing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Systemic Lupus Erythematosus','easy','flashcard','What does the anti-dsDNA antibody indicate in SLE?','["Anti-dsDNA is highly specific for SLE (~70%) and its titer correlates with disease activity particularly lupus nephritis; rising titers predict flares"]','A','Anti-dsDNA and anti-Smith are the two most specific antibodies for SLE. Anti-dsDNA additionally serves as a disease activity marker unlike anti-Smith.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Systemic Lupus Erythematosus','easy','flashcard','What is the most specific antibody for SLE?','["Anti-Smith (anti-Sm) antibody — present in only 25-30% of SLE patients but highly specific (~99%) for SLE; it does not correlate with disease activity"]','A','Anti-Sm targets snRNP proteins involved in RNA splicing. Its very high specificity means a positive result is essentially diagnostic of SLE though sensitivity is low.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Systemic Lupus Erythematosus','medium','flashcard','What is the significance of antiphospholipid antibodies in SLE?','["Antiphospholipid antibodies (lupus anticoagulant anticardiolipin anti-beta2-glycoprotein I) cause a hypercoagulable state leading to thrombosis recurrent miscarriages and a false-positive syphilis (VDRL) test"]','A','Paradoxically the lupus anticoagulant prolongs clotting tests in vitro but causes thrombosis in vivo. False-positive VDRL occurs because cardiolipin is a reagent component.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Systemic Lupus Erythematosus','medium','flashcard','Why are complement levels (C3 and C4) low during active SLE?','["Active SLE is characterized by immune complex deposition that activates the classical complement pathway consuming C3 and C4; low complement levels correlate with disease activity especially nephritis"]','A','Complement consumption by immune complexes makes low C3/C4 a useful disease activity marker; levels rise during remission.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Systemic Lupus Erythematosus','medium','flashcard','What is the wire-loop lesion in lupus nephritis?','["A thickened glomerular capillary wall on light microscopy caused by massive subendothelial immune complex deposits characteristic of Class IV (diffuse proliferative) lupus nephritis"]','A','Wire-loop lesions reflect heavy subendothelial immune complex deposition. Immunofluorescence shows a full-house pattern (IgG IgM IgA C3 C1q all positive).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Systemic Lupus Erythematosus','medium','flashcard','What is Libman-Sacks endocarditis?','["Sterile verrucous (warty) endocarditis in SLE with small irregular vegetations on both surfaces of the mitral and tricuspid valve leaflets caused by antiphospholipid antibody-mediated endothelial injury"]','A','Unlike rheumatic fever (mitral atrial surface only) and infective endocarditis (valve tip irregular) Libman-Sacks vegetations are on both surfaces of the valve and are sterile.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Systemic Lupus Erythematosus','hard','flashcard','Which class of lupus nephritis has the worst prognosis and what defines it histologically?','["Class IV (diffuse proliferative lupus nephritis) has the worst prognosis; involves >50% of glomeruli with endocapillary and extracapillary proliferation wire-loop deposits and crescent formation"]','A','Class IV is the most common cause of renal failure in SLE and requires aggressive immunosuppression (high-dose steroids plus cyclophosphamide or mycophenolate).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Systemic Lupus Erythematosus','hard','flashcard','What HLA associations and demographic features are characteristic of SLE?','["SLE is associated with HLA-DR2 and HLA-DR3; it predominantly affects women of childbearing age with a female-to-male ratio of 9:1 and is more common and severe in African-American and Hispanic women"]','A','The female predominance reflects estrogen''s role in upregulating immune responses. Complement deficiencies (C1q C2 C4) are genetic risk factors for SLE.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Systemic Lupus Erythematosus','hard','flashcard','What serositis manifestations occur in SLE?','["Pleuritis (pleuritic chest pain pleural effusion) and pericarditis are common serositis manifestations; peritonitis is less common; serositis is one of the 11 ACR diagnostic criteria for SLE"]','A','Serositis in SLE results from immune complex deposition in serosal surfaces triggering complement activation and inflammation. Pericarditis is the most common cardiac manifestation.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Ankylosing Spondylitis','easy','flashcard','What is the HLA association of ankylosing spondylitis?','["HLA-B27 is present in >90% of ankylosing spondylitis patients compared to approximately 8% of the general population"]','A','HLA-B27 is the strongest HLA-disease association known. However only ~1-2% of HLA-B27-positive individuals develop AS indicating additional environmental or genetic factors are required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Ankylosing Spondylitis','easy','flashcard','What is the earliest radiological finding in ankylosing spondylitis?','["Bilateral symmetric sacroiliitis seen as sclerosis erosions and eventual fusion of the sacroiliac joints on pelvis X-ray"]','A','Bilateral symmetric sacroiliitis is the hallmark early feature of AS and is required for diagnosis by modified New York criteria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Ankylosing Spondylitis','easy','flashcard','What is the bamboo spine in ankylosing spondylitis?','["Radiological appearance of the spine in advanced AS where vertical bony bridges (syndesmophytes) between vertebral bodies give the spine a bamboo-like appearance on X-ray"]','A','Syndesmophytes in AS are vertical (paravertebral ossification of the annulus fibrosus) distinguishing them from the horizontal osteophytes in diffuse idiopathic skeletal hyperostosis (DISH).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Ankylosing Spondylitis','medium','flashcard','What is enthesitis and why is it characteristic of AS?','["Enthesitis is inflammation at the site of tendon or ligament insertion into bone; it is characteristic of AS and other seronegative spondyloarthropathies leading to reactive bone formation and eventual ankylosis"]','A','Common enthesitis sites include the Achilles tendon insertion plantar fascia origin and vertebral end plates. It is driven by activated immune cells at the enthesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Ankylosing Spondylitis','medium','flashcard','What is the most common extra-articular manifestation of ankylosing spondylitis?','["Anterior uveitis (iritis) occurring in 25-40% of AS patients; presents with acute unilateral eye pain photophobia and redness; typically recurrent and unilateral"]','A','Anterior uveitis in AS is typically acute unilateral and recurrent. It requires urgent ophthalmological assessment as untreated uveitis can lead to vision loss.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Ankylosing Spondylitis','medium','flashcard','How does inflammatory back pain in AS differ from mechanical back pain?','["Inflammatory back pain is worse in the morning and with rest improves with exercise and activity with morning stiffness >1 hour; mechanical pain is worse with activity and improves with rest"]','A','The pattern of morning stiffness improving with movement is a hallmark of AS and other inflammatory arthropathies. Duration >3 months before age 45 with gradual onset raises suspicion for AS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Ankylosing Spondylitis','medium','flashcard','What is the Schober test?','["A clinical test measuring lumbar flexion: marks placed 5 cm below and 10 cm above the lumbosacral junction; normal forward flexion increases the distance by >5 cm; <5 cm indicates restricted lumbar flexion as in AS"]','A','The modified Schober test is a simple bedside test for lumbar mobility. Reduced expansion is an early finding in AS before radiological changes appear.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Ankylosing Spondylitis','medium','flashcard','What is the typical demographic profile of ankylosing spondylitis patients?','["Young males under 40 years of age; male-to-female ratio approximately 2-3:1; onset typically in the second or third decade of life"]','A','AS has a male predominance though it is increasingly recognized in women (who often have milder and atypical presentations including more peripheral joint involvement).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Ankylosing Spondylitis','hard','flashcard','What cardiovascular complication is associated with ankylosing spondylitis?','["Aortic regurgitation (AR) due to aortitis involving the aortic root and proximal aorta; occurs in ~1-4% of AS patients and is more common with longstanding disease"]','A','AS-associated aortitis causes fibrous thickening of the aortic root leading to AR. Atrioventricular conduction defects (heart block) also occur.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Ankylosing Spondylitis','hard','flashcard','What is the treatment hierarchy for ankylosing spondylitis?','["First-line: NSAIDs (symptomatic and possibly disease-modifying); second-line for inadequate response: TNF-alpha inhibitors (adalimumab etanercept infliximab) or IL-17A inhibitors (secukinumab); conventional DMARDs (methotrexate sulfasalazine) do not control axial disease"]','A','Unlike RA conventional DMARDs do not control axial disease in AS. Biologics targeting TNF-alpha or IL-17A are highly effective for axial spondyloarthritis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Psoriatic Arthritis','easy','flashcard','Which skin condition is associated with psoriatic arthritis?','["Psoriasis — a chronic inflammatory skin disease with well-demarcated erythematous plaques with silvery scales; approximately 30% of psoriasis patients develop arthritis"]','A','Psoriatic arthritis (PsA) occurs in up to 30% of patients with psoriasis. The arthritis usually but not always follows the skin disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Psoriatic Arthritis','easy','flashcard','Which joint pattern characterizes psoriatic arthritis and distinguishes it from RA?','["Psoriatic arthritis characteristically involves the DIP (distal interphalangeal) joints which are spared in RA; PsA also shows an asymmetric oligoarthritis pattern"]','A','DIP involvement is a key distinguishing feature of PsA from RA. PsA also shows an asymmetric oligoarthritis pattern whereas RA is symmetric polyarthritis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Psoriatic Arthritis','easy','flashcard','What is dactylitis (sausage digit)?','["Diffuse swelling of an entire digit due to combined flexor tenosynovitis and synovitis of all joints of the digit; characteristic of psoriatic arthritis and other seronegative spondyloarthropathies"]','A','Dactylitis results from inflammation of the tendon sheaths (tenosynovitis) combined with joint synovitis causing uniform swelling of the entire digit.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Psoriatic Arthritis','medium','flashcard','What is the pencil-in-cup deformity and in which condition does it occur?','["Pencil-in-cup deformity on X-ray occurs in psoriatic arthritis: the distal end of the proximal bone is eroded into a pointed pencil shape sitting within an expanded cup-shaped erosion in the distal bone"]','A','Pencil-in-cup deformity reflects severe osteolytic destruction at the DIP joint characteristic of the arthritis mutilans subtype of PsA. It is not seen in RA or OA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Psoriatic Arthritis','medium','flashcard','What nail changes are seen in psoriatic arthritis?','["Nail pitting (most common) onycholysis (separation of nail from nail bed) subungual hyperkeratosis oil-drop discoloration and nail ridging"]','A','Nail changes occur in ~80% of PsA patients and are more common in those with DIP involvement. Nail pitting reflects psoriatic involvement of the nail matrix.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Psoriatic Arthritis','medium','flashcard','What is the serological status of psoriatic arthritis?','["Psoriatic arthritis is seronegative — RF and anti-CCP antibodies are typically absent classifying it as a seronegative spondyloarthropathy"]','A','The absence of RF and anti-CCP helps distinguish PsA from RA especially when both conditions might affect PIP joints.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Psoriatic Arthritis','medium','flashcard','What HLA antigens are associated with psoriatic arthritis?','["HLA-B27 (associated with axial/spinal involvement and sacroiliitis in PsA) and HLA-Cw6 (associated with skin psoriasis especially early-onset plaque psoriasis)"]','A','HLA associations in PsA vary by subtype: HLA-B27 correlates with axial disease and HLA-Cw6 with skin disease reflecting the heterogeneous nature of PsA.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Psoriatic Arthritis','hard','flashcard','What proportion of psoriatic arthritis patients develop sacroiliac involvement and is it symmetric?','["Approximately 20% of PsA patients develop sacroiliac involvement; unlike AS sacroiliitis in PsA is typically asymmetric (unilateral or asymmetric bilateral)"]','A','The asymmetric sacroiliitis of PsA contrasts with the bilateral symmetric sacroiliitis required for AS diagnosis. Asymmetry together with DIP involvement and nail changes helps differentiate PsA from AS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Psoriatic Arthritis','hard','flashcard','Which cytokine is central to both psoriatic skin disease and psoriatic arthritis making it a key therapeutic target?','["IL-17A is central to both skin and joint inflammation in psoriatic disease; IL-23 drives Th17 cell differentiation and IL-17A production making IL-17A inhibitors (secukinumab ixekizumab) and IL-23 inhibitors highly effective"]','A','The IL-23/IL-17 axis is the dominant pathogenic pathway in PsA explaining the efficacy of biologics targeting this pathway for both skin and joint manifestations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Psoriatic Arthritis','hard','flashcard','How does the histology of psoriatic arthritis synovium compare to RA synovium?','["Both show synovial hypertrophy and inflammatory infiltrate (T cells macrophages plasma cells); PsA synovium has more vascularity and tortuous blood vessels less lymphoid aggregate formation and tends to be less destructive with more remissions than RA"]','A','Despite similar histological features PsA has a more favorable course overall than RA with higher remission rates and less joint destruction though arthritis mutilans is a severe destructive subtype.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Bone Tumours','easy','flashcard','What is the most common primary malignant bone tumor?','["Osteosarcoma (osteogenic sarcoma) — a malignant tumor producing osteoid (immature bone) directly from tumor cells"]','A','Osteosarcoma is the most common primary bone malignancy after myeloma (which is technically a hematologic tumor). It accounts for ~20% of all bone sarcomas.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Bone Tumours','easy','flashcard','Where does osteosarcoma most commonly occur within bone?','["The metaphysis of long bones particularly the distal femur and proximal tibia — approximately 50% of cases occur around the knee joint"]','A','The metaphysis is the most vascular part of growing bone where the growth plate is located. The distal femur is the most common single site followed by the proximal tibia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Bone Tumours','easy','flashcard','What is Codman''s triangle in bone tumors?','["A reactive triangular periosteal elevation at the periphery of a bone tumor formed when the tumor lifts the periosteum and new bone is laid down beneath it; classic radiological sign for osteosarcoma"]','A','Codman''s triangle occurs with any rapidly growing tumor or infection elevating the periosteum but is classically associated with osteosarcoma on X-ray.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Bone Tumours','medium','flashcard','What is the sunburst pattern on X-ray in osteosarcoma?','["Radiating spicules of tumor-produced new bone extending outward from the cortex into surrounding soft tissue creating a sun-ray/sunburst appearance on plain radiograph"]','A','The sunburst pattern reflects rapid tumor bone production perpendicular to the periosteum. Together with Codman''s triangle it is a classic radiological feature of osteosarcoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Bone Tumours','medium','flashcard','Where does Ewing sarcoma occur within bone?','["The diaphysis (shaft) of long bones most commonly the femur; also common in flat bones such as the pelvis and ribs with central medullary location"]','A','Ewing sarcoma''s diaphyseal location distinguishes it from osteosarcoma (metaphyseal). Pelvic Ewing sarcoma is associated with poorer prognosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Bone Tumours','medium','flashcard','What is the characteristic chromosomal translocation in Ewing sarcoma?','["t(11;22)(q24;q12) resulting in the EWSR1-FLI1 fusion gene; EWSR1 on chromosome 22 fuses with FLI1 (an ETS transcription factor) on chromosome 11 creating an aberrant transcription factor"]','A','The EWSR1-FLI1 fusion is present in ~85% of Ewing sarcomas and is the primary oncogenic driver detectable by FISH or RT-PCR for diagnosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Bone Tumours','medium','flashcard','What is the histological appearance of Ewing sarcoma?','["Sheets of small round blue cells (undifferentiated) with round nuclei and scant cytoplasm arranged in pseudorosettes (Homer Wright rosettes); glycogen-rich cytoplasm (PAS-positive) and CD99 (MIC2) positive"]','A','Ewing sarcoma belongs to the Ewing family of tumors (primitive neuroectodermal tumor/PNET). PAS staining and CD99 immunohistochemistry are helpful diagnostic markers.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Bone Tumours','medium','flashcard','What periosteal reaction is classic for Ewing sarcoma on X-ray?','["Onion-skin periosteal reaction — multiple concentric layers of reactive periosteal new bone surrounding the cortex resembling the layers of an onion"]','A','The onion-skin pattern reflects repeated episodes of periosteal elevation and new bone formation as the tumor expands. It is characteristic but not pathognomonic of Ewing sarcoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Bone Tumours','hard','flashcard','What are the location and histological features of giant cell tumor of bone?','["Giant cell tumor (GCT) arises in the epiphysis of long bones in skeletally mature adults (20-40 years) most commonly distal femur and proximal tibia; histologically contains osteoclast-type multinucleated giant cells evenly distributed among mononuclear stromal cells"]','A','GCT stromal cells express RANKL driving osteoclast recruitment. Denosumab (anti-RANKL) treats unresectable GCT. Approximately 5-10% behave malignantly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Bone Tumours','hard','flashcard','What is the bimodal age distribution of osteosarcoma and what accounts for the second peak?','["First peak: ages 10-20 years (related to rapid bone growth during adolescent growth spurt); second peak: elderly (>60 years) most commonly arising in Paget''s disease of bone or after prior radiation"]','A','Adolescent osteosarcoma relates to the growth spurt (metaphyseal proliferating bone). Paget''s disease is the most common predisposing condition for osteosarcoma in the elderly with sarcomatous transformation in <1%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Soft Tissue Tumours','easy','flashcard','What is the most common benign soft tissue tumor?','["Lipoma — a benign tumor of mature adipocytes most commonly found in the subcutaneous tissue of the trunk neck and proximal extremities"]','A','Lipomas are the most common mesenchymal neoplasms; they are soft mobile encapsulated and painless. Deep intramuscular lipomas may require excision to exclude liposarcoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Soft Tissue Tumours','easy','flashcard','What is the most common soft tissue sarcoma in children?','["Rhabdomyosarcoma — a malignant tumor of skeletal muscle origin; most common in children and adolescents affecting the head/neck genitourinary tract and extremities"]','A','Rhabdomyosarcoma is the most common soft tissue sarcoma in patients under 20 years. Embryonal rhabdomyosarcoma is the most common subtype in young children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Soft Tissue Tumours','easy','flashcard','What immunohistochemical markers identify rhabdomyosarcoma?','["Desmin (intermediate filament of muscle) and MyoD1 (muscle regulatory transcription factor); both are positive in rhabdomyosarcoma confirming skeletal muscle differentiation"]','A','MyoD1 is a myogenic transcription factor specific to skeletal muscle lineage making it highly specific for rhabdomyosarcoma among soft tissue tumors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Soft Tissue Tumours','medium','flashcard','What mutation defines GIST and what targeted therapy exploits it?','["GIST is defined by gain-of-function mutation in the KIT gene (encoding CD117 a tyrosine kinase receptor) present in ~85% of cases; imatinib (Gleevec) a tyrosine kinase inhibitor specifically targets KIT and is highly effective"]','A','KIT mutations constitutively activate the receptor driving proliferation. ~10% of GISTs have PDGFRA mutations (also targeted by imatinib). GIST was one of the first cancers treated by targeted molecular therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Soft Tissue Tumours','medium','flashcard','What is a lipoblast and in which tumor is it the diagnostic cell?','["A lipoblast is a neoplastic adipocyte precursor with a scalloped nucleus indented by cytoplasmic lipid vacuoles (signet-ring appearance); it is the diagnostic cell of liposarcoma"]','A','The presence of lipoblasts is required for the diagnosis of liposarcoma. The most common liposarcoma subtype is well-differentiated liposarcoma (atypical lipomatous tumor) of the retroperitoneum.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Soft Tissue Tumours','medium','flashcard','What is the most common malignant soft tissue tumor in adults and where does it typically occur?','["Liposarcoma is the most common soft tissue sarcoma in adults; most commonly in the retroperitoneum and deep soft tissues of the extremities (especially the thigh)"]','A','Retroperitoneal liposarcomas present late due to their large size. The well-differentiated subtype (atypical lipomatous tumor) has a low risk of metastasis but locally recurs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Soft Tissue Tumours','medium','flashcard','What is the chromosomal translocation in synovial sarcoma?','["t(X;18)(p11;q11) resulting in SS18-SSX1 or SS18-SSX2 fusion gene; present in >90% of synovial sarcomas and used diagnostically by FISH or RT-PCR"]','A','Despite its name synovial sarcoma rarely arises from synovium. It most commonly occurs around large joints of the extremities in young adults.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Soft Tissue Tumours','medium','flashcard','What is the histological appearance of synovial sarcoma?','["Biphasic pattern: epithelioid cells forming gland-like spaces (cytokeratin-positive) admixed with spindle cells (fibroblast-like); monophasic (spindle cell only) and poorly differentiated subtypes also exist"]','A','The biphasic pattern of synovial sarcoma is unusual for a sarcoma. Cytokeratin and EMA positivity in a sarcoma strongly suggest synovial sarcoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Soft Tissue Tumours','hard','flashcard','What is a desmoid tumor (deep fibromatosis) and what hereditary condition is it associated with?','["A desmoid tumor is a locally aggressive but non-metastasizing myofibroblastic neoplasm; strongly associated with familial adenomatous polyposis (FAP/Gardner syndrome) due to APC gene mutations leading to beta-catenin accumulation in fibroblasts"]','A','Desmoids in FAP (Gardner syndrome) typically arise in the mesentery. Sporadic desmoids often occur post-partum or at surgical scars. They recur locally but never metastasize.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Soft Tissue Tumours','hard','flashcard','What common sites does leiomyosarcoma affect and what is its cell of origin?','["Leiomyosarcoma is a malignant tumor of smooth muscle; most common sites are the uterus (most common uterine sarcoma) and retroperitoneum; also arises in large blood vessel walls such as the inferior vena cava"]','A','Leiomyosarcoma should be distinguished from leiomyoma (benign) by increased mitoses nuclear atypia and coagulative necrosis. Uterine leiomyosarcoma carries a poor prognosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Septic Arthritis & Osteomyelitis','easy','flashcard','What is the most common causative organism in septic arthritis and osteomyelitis in adults and children >2 years?','["Staphylococcus aureus is the most common organism in septic arthritis and osteomyelitis across most age groups including adults and children over 2 years"]','A','S. aureus is the dominant organism due to its virulence factors (protein A coagulase toxins) and tendency to seed joints and bone from bacteremia. MRSA is an increasing concern.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Septic Arthritis & Osteomyelitis','easy','flashcard','What organism causes septic arthritis in sexually active young adults?','["Neisseria gonorrhoeae — gonococcal arthritis is the most common cause of septic arthritis in sexually active adults under 40 years"]','A','Gonococcal arthritis presents as migratory arthritis tenosynovitis and skin pustules (disseminated gonococcal infection). It responds rapidly to antibiotics and rarely causes permanent joint damage.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Septic Arthritis & Osteomyelitis','easy','flashcard','What is Pott''s disease?','["Tuberculous osteomyelitis of the spine (vertebral TB); typically affects the lower thoracic and upper lumbar vertebrae causing vertebral body destruction gibbus deformity and cold (psoas) abscess"]','A','Pott''s disease results from hematogenous spread of M. tuberculosis to the spine. The disc space is initially preserved distinguishing it from pyogenic spondylodiscitis where the disc is destroyed early.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Septic Arthritis & Osteomyelitis','medium','flashcard','What is a sequestrum in osteomyelitis?','["A fragment of dead devascularized (necrotic) bone that has become separated from surrounding living bone during osteomyelitis; it appears radiodense on X-ray and acts as a nidus for chronic infection"]','A','Sequestra persist because avascular bone cannot be reached by antibiotics or immune cells. Surgical removal (sequestrectomy) is often required for cure in chronic osteomyelitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Septic Arthritis & Osteomyelitis','medium','flashcard','What is an involucrum in osteomyelitis?','["A shell of periosteal new bone that forms around a sequestrum (dead bone fragment) in chronic osteomyelitis; represents the periosteum''s attempt to contain the infection and support the damaged bone"]','A','The involucrum forms as the elevated periosteum produces new bone to wall off the infected area. Together the sequestrum (dead bone) and involucrum (reactive new bone) are hallmarks of chronic osteomyelitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Septic Arthritis & Osteomyelitis','medium','flashcard','What organism causes osteomyelitis disproportionately in sickle cell disease patients?','["Salmonella species (especially Salmonella typhimurium) cause osteomyelitis disproportionately in sickle cell disease; S. aureus remains the most common overall organism even in sickle cell patients but Salmonella is the classic association"]','A','Functional asplenia in sickle cell disease reduces clearance of encapsulated organisms and promotes Salmonella bacteremia. Salmonella osteomyelitis in sickle cell is a classic exam association.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Septic Arthritis & Osteomyelitis','medium','flashcard','What is a Brodie abscess?','["A chronic localized subacute osteomyelitis presenting as a walled-off abscess within the metaphysis of a long bone most commonly caused by S. aureus; appears as a lytic lesion with a sclerotic border on X-ray"]','A','Brodie abscess represents subacute osteomyelitis where the host immune response partially contains the infection. It is treated surgically with curettage plus antibiotics.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Septic Arthritis & Osteomyelitis','hard','flashcard','Why does hematogenous osteomyelitis in children preferentially affect the metaphysis?','["The metaphysis has a rich sinusoidal vascular network with sluggish blood flow and few phagocytic cells; the tortuous sinusoidal capillaries terminate in venous sinusoids with abrupt change in blood flow velocity allowing bacteria to settle and multiply"]','A','The unique vasculature of the metaphysis (the most rapidly growing and vascular part of bone) explains why hematogenous infection targets this site. After puberty growth plate closure changes this pattern.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Septic Arthritis & Osteomyelitis','hard','flashcard','What are the microbiology and risk factors for diabetic foot osteomyelitis?','["Diabetic foot osteomyelitis is typically polymicrobial; S. aureus is the most common single organism but Gram-negative rods and anaerobes are also frequently present; risk factors include peripheral neuropathy vascular insufficiency and immune dysfunction"]','A','Polymicrobial infection requires broad-spectrum antibiotics covering Gram-positives (including MRSA) Gram-negatives and anaerobes. The probe-to-bone test through an ulcer is highly specific for osteomyelitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Septic Arthritis & Osteomyelitis','hard','flashcard','What was the previously common organism for osteomyelitis in children under 2 years and why is it now rare?','["Haemophilus influenzae type b (Hib) was a common cause of septic arthritis and osteomyelitis in children <2 years before vaccination; universal Hib conjugate vaccine programs have made this entity extremely rare"]','A','The Hib vaccine introduced in the late 1980s dramatically reduced invasive H. influenzae disease including osteomyelitis and meningitis in young children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Paget''s Disease of Bone','easy','flashcard','What are the three phases of Paget''s disease of bone?','["Phase 1 (osteolytic): osteoclast-dominant bone resorption; Phase 2 (mixed): concurrent osteoclast resorption and osteoblast formation; Phase 3 (osteosclerotic/burned-out): osteoblast-dominant with dense disorganized sclerotic bone"]','A','The three phases reflect progressive shift from resorption to formation. The burned-out phase produces structurally weak enlarged pagetic bone despite appearing dense on X-ray.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Paget''s Disease of Bone','easy','flashcard','What is the histological hallmark of Paget''s disease?','["The mosaic (jigsaw puzzle) pattern of lamellar bone — irregular cement lines from repeated cycles of resorption and repair create a patchwork appearance pathognomonic of Paget''s disease"]','A','Cement lines represent boundaries between successive cycles of bone resorption and formation. The mosaic pattern is the diagnostic histological hallmark of Paget''s disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Paget''s Disease of Bone','easy','flashcard','Which laboratory test is markedly elevated in Paget''s disease and what is normal?','["Serum alkaline phosphatase (ALP) is markedly elevated reflecting intense osteoblastic activity; serum calcium and phosphate remain normal"]','A','Elevated ALP is the most sensitive biochemical marker of Paget''s disease activity and is used to monitor treatment response (bisphosphonates should normalize ALP). Normal calcium distinguishes Paget''s from hyperparathyroidism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Paget''s Disease of Bone','medium','flashcard','What skull changes occur in Paget''s disease?','["Cotton-wool appearance on skull X-ray (mixed lytic and sclerotic lesions); skull enlargement (hat-band sign — increased hat size); sensorineural or conductive hearing loss due to encroachment on the cochlea or ossicles"]','A','Pagetic skull involvement leads to the cotton-wool X-ray appearance. Hearing loss is a common cranial nerve complication; basilar invagination can compress the brainstem.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Paget''s Disease of Bone','medium','flashcard','What is the most feared complication of Paget''s disease of bone?','["Sarcomatous transformation — osteosarcoma arising in pagetic bone (less commonly chondrosarcoma or fibrosarcoma); occurs in <1% of patients but carries extremely poor prognosis with <10% 5-year survival"]','A','Sudden onset of severe pain or rapid enlargement in a known Paget''s patient should prompt imaging for sarcomatous transformation. Pagetic osteosarcoma is far more lethal than conventional osteosarcoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Paget''s Disease of Bone','medium','flashcard','What cardiovascular complication can occur in extensive Paget''s disease?','["High-output cardiac failure — extensive pagetic bone has markedly increased vascularity (arteriovenous shunting within bone) increasing total peripheral blood flow and cardiac output; prolonged high output leads to cardiac failure"]','A','High-output cardiac failure in Paget''s disease is analogous to that in severe anemia or thyrotoxicosis — the heart fails because it cannot sustain chronically elevated output demands.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Paget''s Disease of Bone','medium','flashcard','What tibial deformity is characteristic of Paget''s disease?','["Anterior bowing of the tibia (sabre tibia) — due to softening and deformity of structurally weak pagetic cortical bone under normal weight-bearing stress"]','A','The sabre tibia of Paget''s disease should be distinguished from the anterior bowing of syphilitic osteitis (also called sabre tibia) — context and other features differentiate them.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Paget''s Disease of Bone','medium','flashcard','What is the most common presenting symptom of Paget''s disease and which bones are most commonly involved?','["Deep aching bone pain worse at night; most commonly involved bones are the pelvis (most frequent) lumbar spine femur skull and tibia; ~70% of patients are asymptomatic"]','A','Bone pain results from increased vascularity and periosteal stretching from bone expansion. Many cases are discovered incidentally by elevated ALP on routine blood tests.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Paget''s Disease of Bone','hard','flashcard','What is the proposed etiology of Paget''s disease?','["A paramyxoviral etiology has been proposed — inclusion bodies resembling paramyxovirus nucleocapsids (measles respiratory syncytial virus) have been found in osteoclast nuclei; SQSTM1/p62 gene mutations are found in familial cases disrupting RANKL signaling in osteoclasts"]','A','The viral hypothesis (paramyxovirus trigger in genetically susceptible individuals) is the leading but unproven theory. SQSTM1 mutations are found in familial Paget''s disease.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES ('{"medicine"}','Medicine','Musculoskeletal System','Pathology','Paget''s Disease of Bone','hard','flashcard','What is the geographic distribution and typical age of onset of Paget''s disease?','["Common in the UK Western Europe Australia and New Zealand but rare in Asia and Africa; typically presents after age 55 with average age of onset around 70 years"]','A','The geographic clustering of Paget''s disease supports an environmental (possibly viral) trigger in genetically predisposed populations. The condition is asymptomatic in approximately 70% of patients.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
